def semver_sort(versions):
    def parse(v):
        # split build metadata
        main = v.split('+', 1)[0]
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core, pre = main, None
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is None:
            pre_key = (1,)  # no prerelease, sorts after
        else:
            ids = pre.split('.')
            parts = []
            for ident in ids:
                if ident.isdigit():
                    parts.append((0, int(ident)))
                else:
                    parts.append((1, ident))
            pre_key = (0, parts)
        return (major, minor, patch, pre_key)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse(pair[1]), pair[0]))
    return [v for _, v in indexed]

